CREATE TYPE "WebsitePlanTier" AS ENUM ('EDITOR', 'CARE', 'MANAGED');
CREATE TYPE "WebsitePurchaseStatus" AS ENUM ('PAYMENT_PENDING', 'SETUP_PAID', 'SETUP_IN_PROGRESS', 'READY', 'ACTIVE', 'FAILED', 'CANCELLED');
CREATE TYPE "ManagedBookingStatus" AS ENUM ('REQUESTED', 'CONFIRMED', 'COMPLETED', 'CANCELLED');
CREATE TABLE "WebsitePurchase" ("id" TEXT NOT NULL, "clientId" TEXT NOT NULL, "invoiceId" TEXT, "productId" TEXT NOT NULL, "tier" "WebsitePlanTier" NOT NULL, "status" "WebsitePurchaseStatus" NOT NULL DEFAULT 'PAYMENT_PENDING', "businessName" TEXT NOT NULL, "contactName" TEXT NOT NULL, "email" TEXT NOT NULL, "phone" TEXT, "websiteUrl" TEXT NOT NULL, "notes" TEXT, "compatibilityStatus" TEXT NOT NULL, "compatibilityNotes" TEXT, "monthlyPrice" DECIMAL(12,2) NOT NULL, "setupPrice" DECIMAL(12,2) NOT NULL, "currency" TEXT NOT NULL DEFAULT 'GHS', "setupPaidAt" TIMESTAMP(3), "activatedAt" TIMESTAMP(3), "nextBillingAt" TIMESTAMP(3), "paymentAuthorization" TEXT, "providerPlanCode" TEXT, "providerSubscriptionCode" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "WebsitePurchase_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ManagedBooking" ("id" TEXT NOT NULL, "businessName" TEXT NOT NULL, "contactName" TEXT NOT NULL, "email" TEXT NOT NULL, "phone" TEXT NOT NULL, "websiteUrl" TEXT NOT NULL, "reason" TEXT NOT NULL, "goals" TEXT NOT NULL, "notes" TEXT, "requestedAt" TIMESTAMP(3) NOT NULL, "status" "ManagedBookingStatus" NOT NULL DEFAULT 'REQUESTED', "adminNotes" TEXT, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "ManagedBooking_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "WebsitePurchase_invoiceId_key" ON "WebsitePurchase"("invoiceId");
CREATE INDEX "WebsitePurchase_status_createdAt_idx" ON "WebsitePurchase"("status", "createdAt");
CREATE INDEX "WebsitePurchase_clientId_tier_idx" ON "WebsitePurchase"("clientId", "tier");
CREATE INDEX "ManagedBooking_status_requestedAt_idx" ON "ManagedBooking"("status", "requestedAt");
ALTER TABLE "WebsitePurchase" ADD CONSTRAINT "WebsitePurchase_clientId_fkey" FOREIGN KEY ("clientId") REFERENCES "Client"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "WebsitePurchase" ADD CONSTRAINT "WebsitePurchase_invoiceId_fkey" FOREIGN KEY ("invoiceId") REFERENCES "Invoice"("id") ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE "WebsitePurchase" ADD CONSTRAINT "WebsitePurchase_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
UPDATE "Product" SET "name"='Editor', "tagline"='Self-service website editing for one website and up to two users.', "monthlyPrice"=450.00, "setupPrice"=1500.00, "sortOrder"=1 WHERE "key"='website-builder' AND "monthlyPrice" IN (300.00, 750.00);
